{
  "technical_and_design_decisions": [
    "Spring XD is the target platform (built on Spring Framework, Spring Boot, Spring Integration, Spring Batch).",
    "User stories U1-U7 require changes to Spring XD runtime, modules, documentation, and CI infrastructure.",
    "U2: Job module lifecycle change requires modifications to module deployment and job launch logic in Spring XD container.",
    "U3: Spark streaming tap feature requires changes to Spark module and possibly Spring XD tap/analytics integration.",
    "U4: Metrics integration uses Spring Boot Actuator's MetricRepository and export() API; requires exposing module-specific metrics.",
    "U5: Module options migration to Spring Boot property sources and configuration metadata (spring-configuration-metadata.json).",
    "U6: Externalized configuration for XD-Admin and XD-Container using Spring Cloud Config or similar central property management.",
    "U7: RabbitMQ performance troubleshooting involves profiling, bottleneck analysis, and potential broker/client tuning.",
    "U8: CI migration to EC2 involves provisioning instances, configuring build agents (Jenkins/GitHub Actions), and migrating pipelines."
  ],
  "assumptions": [
    "Developer has deep familiarity with Spring XD codebase, Spring Boot, Spring Integration, Spring Batch, Spark, RabbitMQ, and CI/CD tools.",
    "Existing test infrastructure (unit, integration) can be extended; no new test frameworks required.",
    "Documentation updates are in AsciiDoc/Markdown within the Spring XD repo.",
    "EC2 instances for CI are provisioned via existing AWS account; IAM permissions available.",
    "Performance benchmarks (U1) run on existing hardware; no new cluster procurement needed.",
    "RabbitMQ performance issues (U7) are reproducible in a staging environment.",
    "All changes target the Spring XD MASTER branch (pre-1.0 or 1.x).",
    "No major dependency upgrades (Spring Framework, Spring Boot) are required beyond what's compatible.",
    "Effort estimates include design, coding, unit testing, code review, and documentation for each activity.",
    "Integration testing and QA are performed by the same developer within the estimated hours."
  ],
  "activities": [
    {
      "activity_id": "A1.1",
      "activity_name": "Design benchmark suite and infrastructure metadata capture",
      "activity_description": "Define benchmark scenarios, metrics to collect (throughput, latency, resource usage), and infrastructure details (JDK, OS, cluster topology) for Spring XD cluster reference.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A1.2",
      "activity_name": "Implement automated benchmark tests",
      "activity_description": "Write performance test scripts (using JMeter/Gatling or Spring XD's own test framework) for key XD workloads (streams, jobs, taps). Include infrastructure metadata logging.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A1.3",
      "activity_name": "Document benchmarks and publish results",
      "activity_description": "Create documentation (AsciiDoc) with benchmark results, infrastructure specifics, and guidelines for cluster setup. Add to Spring XD reference guide.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2.1",
      "activity_name": "Redesign job module lifecycle management",
      "activity_description": "Modify Spring XD container to bootstrap job module context only at job launch (via JobLaunchRequest) and shut down after completion. Update module registry and deployment logic.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A2.2",
      "activity_name": "Implement lazy job module bootstrap and shutdown",
      "activity_description": "Code changes in module deployment, job plugin, and container runtime. Ensure proper resource cleanup (threads, connections) on shutdown. Handle error scenarios.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A2.3",
      "activity_name": "Test resource utilization improvements",
      "activity_description": "Write integration tests verifying context bootstrap/shutdown behavior, memory/thread usage before and after. Validate with multiple concurrent job launches.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A3.1",
      "activity_name": "Implement tap at Spark module output",
      "activity_description": "Add tap support to Spark streaming module (SparkReceiverModule, SparkProcessorModule) to allow downstream analytics. Integrate with XD tap infrastructure.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A3.2",
      "activity_name": "Update Spark streaming examples",
      "activity_description": "Revise existing Spark streaming samples (e.g., Twitter, Kafka) to demonstrate new tap feature. Ensure examples run in current XD distribution.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A3.3",
      "activity_name": "Enhance documentation for Reliable receiver",
      "activity_description": "Add detailed documentation on Spark Reliable receiver configuration, fault tolerance, checkpointing, and exactly-once semantics. Include in reference guide.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4.1",
      "activity_name": "Integrate Boot Actuator MetricRepository for module metrics",
      "activity_description": "Configure Spring Boot Actuator in XD modules. Expose module-specific metrics (counters, gauges) via MetricRepository. Ensure metrics are tagged with module/app context.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4.2",
      "activity_name": "Implement metric export and consumption API",
      "activity_description": "Use Actuator's export() API to push metrics to external systems (e.g., Redis, JMX, HTTP). Provide REST endpoint for ad-hoc metric queries per module.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A4.3",
      "activity_name": "Test and document module metrics",
      "activity_description": "Verify metrics collection for various module types (source, processor, sink, job). Document available metrics, tags, and how to consume them.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A5.1",
      "activity_name": "Refactor module options to Boot property sources",
      "activity_description": "Replace custom module option handling in XD runtime with Spring Boot's PropertySource abstraction. Map module options to @ConfigurationProperties beans.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A5.2",
      "activity_name": "Generate configuration metadata for module options",
      "activity_description": "Produce spring-configuration-metadata.json for all module options using Spring Boot's configuration metadata annotation processor. Include descriptions, types, default values.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A5.3",
      "activity_name": "Remove legacy module option management from core runtime",
      "activity_description": "Delete deprecated ModuleOptionMetadata, ModuleOptionResolver, and related classes. Update module deployment to use new property source mechanism.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6.1",
      "activity_name": "Design central external configuration management",
      "activity_description": "Define architecture for centralized configuration (Spring Cloud Config Server or Consul/Etcd). Determine client-side bootstrap for XD-Admin and XD-Container.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A6.2",
      "activity_name": "Implement externalized configuration for XD-Admin and XD-Container",
      "activity_description": "Add Spring Cloud Config client dependencies. Configure bootstrap.yml for both servers. Implement environment-specific property resolution (profiles, labels). Secure sensitive properties.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A6.3",
      "activity_name": "Test configuration across environments",
      "activity_description": "Validate configuration refresh, encryption/decryption, and fallback behavior in dev, staging, prod profiles. Document setup for operators.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7.1",
      "activity_name": "Profile RabbitMQ message bus performance",
      "activity_description": "Set up profiling environment (YourKit, JFR). Run load tests with RabbitMQ as transport. Identify bottlenecks: connection management, prefetch, serialization, queue declaration, broker config.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A7.2",
      "activity_name": "Implement RabbitMQ performance fixes",
      "activity_description": "Apply fixes: tune connection factory, prefetch count, publisher confirms, lazy queues, serialization (protobuf/avro), broker policies. Update XD RabbitMQ binder configuration.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A7.3",
      "activity_name": "Benchmark and verify RabbitMQ improvements",
      "activity_description": "Run comparative benchmarks before/after fixes. Measure throughput, latency, CPU/memory. Document optimal configurations for different workloads.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A8.1",
      "activity_name": "Provision and configure EC2 instances for CI",
      "activity_description": "Launch EC2 instances (Linux, appropriate size). Install JDK, Maven/Gradle, Docker, build tools. Configure security groups, IAM roles, and SSH access.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A8.2",
      "activity_name": "Migrate MASTER branch CI pipelines to EC2",
      "activity_description": "Move Jenkins jobs / GitHub Actions workflows to new EC2 agents. Update pipeline scripts (Groovy/YAML) for new environment. Configure artifact storage (S3/Nexus).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A8.3",
      "activity_name": "Validate and monitor CI builds on EC2",
      "activity_description": "Run test builds for MASTER branch. Verify all stages (compile, test, integration, deploy). Set up monitoring (CloudWatch, logs) and alerting for build failures.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 560
  }
}

